SELECT
    #{date} AS dtStats,
    COUNT(*) AS inCnt,
    IFNULL(SUM(CASE WHEN rslt_val = '0' OR rslt_val = '1000' THEN 1 ELSE 0 END), 0) AS succCnt,
    IFNULL(SUM(CASE WHEN rslt_val IN ('9999', '-1') THEN 1 ELSE 0 END), 0) AS errorCnt,
    IFNULL(SUM(CASE WHEN rslt_val NOT IN ('0', '1000', '9999', '-1', '') AND rslt_val IS NOT NULL THEN 1 ELSE 0 END), 0) AS failCnt,
    0 AS ingCnt,
    0 AS waitCnt
FROM ${tableName}

    DATE(rslt_date) = #{date}

        AND user_id = #{userId}


        AND user_id IN

            #{uid}



        AND msg_type = #{msgType}




                AND (ext_col0 IS NULL OR ext_col0 = '')


                AND ext_col0 IS NOT NULL AND ext_col0 != ''

SELECT COUNT(*)
FROM msg_queue

    stat = '0'
    AND DATE(request_time) = #{date}
    AND request_time > NOW()

        AND ext_col3 = #{userId}


        AND ext_col3 IN

            #{uid}



        AND msg_type = #{msgType}




                AND (ext_col0 IS NULL OR ext_col0 = '')


                AND ext_col0 IS NOT NULL AND ext_col0 != ''

SELECT COUNT(*)
FROM msg_queue

    stat IN ('1', '2')
    AND DATE(request_time) = #{date}
    AND request_time <= NOW()

        AND ext_col3 = #{userId}


        AND ext_col3 IN

            #{uid}



        AND msg_type = #{msgType}




                AND (ext_col0 IS NULL OR ext_col0 = '')


                AND ext_col0 IS NOT NULL AND ext_col0 != ''
